55	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
56	    throw new HttpError(400, 'INVALID_DOCUMENT', 'document must be an object');
57	  }
58	  for (const key of Object.keys(data)) {
59	    if (!DOCUMENT_FIELDS.has(key)) {
60	      throw new HttpError(400, 'INVALID_DOCUMENT', `unknown document field: ${key}`);
61	    }
62	  }
63	  for (const key of ['id', 'title', 'body']) {
64	    if (typeof data[key] !== 'string' || !data[key].trim()) {
