228	  }
229	  try {
230	    fs.renameSync(snapshotTemp, snapshotFile);
231	  } catch (error) {
232	    try {
233	      if (hadHistory) {
234	        fs.renameSync(backupFile, historyFile);
235	      } else {
236	        fs.rmSync(historyFile, { force: true });
237	      }
238	    } catch {
239	      // startup recovery reconciles whatever remains
240	    }
241	    removeQuiet(historyTemp);
242	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${snapshotFile}: ${error.message}`);
243	  }
244	  removeQuiet(backupFile);
