59	    method,
60	    headers: {
61	      ...(body !== undefined || rawBody !== undefined ? { 'content-type': 'application/json' } : {}),
62	      ...headers,
63	    },
64	    body: rawBody ?? (body !== undefined ? JSON.stringify(body) : undefined),
65	  });
66	  const text = await response.text();
67	  return {
68	    status: response.status,
69	    etag: response.headers.get('etag'),
70	    body: text ? JSON.parse(text) : null,
71	  };
72	}
